class Solution {
    public boolean containsNearbyDuplicate(int[] nums, int k) {
        Map<Integer, Integer> helper = new HashMap<>();
        for (int i = 0, n = nums.length; i < n; ++i) {
            if (helper.containsKey(nums[i])) {
                int j = helper.get(nums[i]);
                if (i - j <= k) {
                    return true;
                }
            }
            helper.put(nums[i], i);
        }
        return false;
    }
}

from typing import List

class Solution:
    def containsNearbyDuplicate(self, nums: List[int], k: int) -> bool:
        window = set()
        l = 0

        for r in range(len(nums)):
            if r - l > k:
                window.discard(nums[l])
                l += 1
            if nums[r] in window:
                return True
            window.add(nums[r])

        return False

class Solution:
    def containsNearbyDuplicate(self, nums: List[int], k: int) -> bool:
        contains_dup = False
        seen = dict()
        for i, num in enumerate(nums):
            val = seen.get(num, -1)
            if val == -1:
                seen[num] = i
            elif abs(val - i) <= k:
                contains_dup = True
                break
            else:
                seen[num] = i
        return contains_dup

