class Solution {
public:
    bool containsNearbyDuplicate(vector<int>& nums, int k) {
        unordered_set<int> ust;
        int n=nums.size();
        for(int i=0;i<n;i++)
        {
            if(i>k)
                ust.erase(nums[i-k-1]);
            if(ust.find(nums[i])!=ust.end())
                return true;
            ust.insert(nums[i]);
        }
        return false;
    }
};

from collections import Counter
class Solution:
    # @param {integer[]} nums
    # @param {integer} k
    # @return {boolean}
    def containsNearbyDuplicate(self, nums, k):
        c = Counter(nums[:k])
        for val in c.values():
            if val>1:
                return True
        start = 0
        end = k
        while end < len(nums):
            if c[nums[end]]>0:
                return True
            c[nums[start]]-=1
            c[nums[end]]+=1
            start += 1
            end += 1
        return False

class Solution(object):
    def containsNearbyDuplicate(self, nums, k):
        """
        :type nums: List[int]
        :type k: int
        :rtype: bool
        """
        ind_dict = {}
        for i, num in enumerate(nums):
            if num in ind_dict:
                if i - ind_dict[num] <= k:
                    return True
            ind_dict[num] = i
        return False
